#include <stdio.h>
int main(void) {
    char *s = "abc";
    int h = 0;
    for (int i = 0; s[i]; i++) h += s[i];
    printf("%d\n", h % 8);
    return 0;
}

#include <stdio.h>
int main(void) {
    char *s = "abab";
    int freq[26] = {0};
    for (int i = 0; s[i]; i++) freq[s[i] - 'a']++;
    printf("%d %d\n", freq[0], freq[1]);
    return 0;
}

#include <stdio.h>
int main(void) {
    int a[] = {4, 7, 4, 9};
    int seen[10] = {0};
    int dup = 0;
    for (int i = 0; i < 4; i++) {
        if (seen[a[i]]) dup = a[i];
        seen[a[i]] = 1;
    }
    printf("%d\n", dup);
    return 0;
}

#include <stdio.h>
int main(void) {
    int keys[] = {10, 17, 24, 31};
    int bucket[7] = {0};
    int coll = 0;
    for (int i = 0; i < 4; i++) {
        int h = keys[i] % 7;
        if (bucket[h] > 0) coll++;
        bucket[h]++;
    }
    printf("%d\n", coll);
    return 0;
}

#include <stdio.h>
int main(void) {
    char *a = "listen", *b = "silent";
    int f[26] = {0}, bal = 1;
    for (int i = 0; a[i]; i++) f[a[i] - 'a']++;
    for (int i = 0; b[i]; i++) f[b[i] - 'a']--;
    for (int i = 0; i < 26; i++)
        if (f[i]) bal = 0;
    printf("%d\n", bal);
    return 0;
}
